import{z as B,x as p,o as n,c as A,q as i,j as o,D as t,d as e,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"期权组合策略","description":"","frontmatter":{"title":"期权组合策略","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/option-strategies.md","filePath":"quant/option-strategies.md","lastUpdated":1791063341000}'),d={name:"quant/option-strategies.md"};function m(h,a,u,c,g,D){const r=p("Mermaid");return n(),A("div",null,[a[2]||(a[2]=i('<h1 id="期权组合策略" tabindex="-1">期权组合策略 <a class="header-anchor" href="#期权组合策略" aria-label="Permalink to &quot;期权组合策略&quot;">​</a></h1><div class="epigraph"><p>价差、跨式、风险反转是香草的线性组合；它们改的是支付的分段斜率，不是新的路径统计量。</p><footer>—— Natenberg, Option Volatility and Pricing；对照 McMillan 对价差组合的经典分类</footer></div><p><a href="/quant/compound-chooser">上一课</a>还在「期权上的期权」。本课把已经会的香草<strong>拼成簿</strong>：垂直价差、日历、跨式跨式、蝶式、风险反转、领口。缺口是工程而不是新闭式——支付图、希腊值如何相消、以及哪些组合其实已经是数字或偏斜仓。后课权证与结构票据会把这些组合嵌进零售包装。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>奇异课序写到这里，容易把一切都当路径依赖。市场里最大量的「结构」仍是香草线性组合：牛市价差 \\(=\\) 买低 \\(K\\) 看涨、卖高 \\(K\\) 看涨，支付有界，净 Vega 与净 Gamma 比裸期权小。问题是：组合的<strong>报价惯例</strong>（按净权利金、按借/贷、按隐波差）与<strong>风险报告</strong>（按腿加总还是按组合再取曲面）经常不一致。把蝶式当三个独立 Vega 去对冲，会在执行价网格上把流动性最差的那条腿放最大。</p><p>日历价差吃的是期限结构与远期波动，不是同一到期的偏斜；风险反转吃的是偏斜，不是水平。对象已经在 <a href="/quant/vol-skew">Skew</a> 与 <a href="/quant/vol-surface">隐波曲面</a> 里，本课只把组合语言接上，不重校准曲面。</p><h3 id="垂直价差的极限是数字" tabindex="-1">垂直价差的极限是数字 <a class="header-anchor" href="#垂直价差的极限是数字" aria-label="Permalink to &quot;垂直价差的极限是数字&quot;">​</a></h3><p>相邻执行价的看涨价差，除以 \\(\\Delta K\\)，就是 <a href="/quant/digital-options">数字</a> 的复制。蝶式除以 \\((\\Delta K)^2\\) 逼近密度。因此「策略」与「奇异」之间没有形而上学的边界：足够密的香草组合就是静态复制。实务网格稀疏、买卖价差宽，复制有残差，这才需要真正的奇异合约。</p><p><span class="marginnote">领口（collar）= 长标的 + 买跌 + 卖涨，常被当成「保值」。卖出的看涨是融资，不是免费保险。结构票据里的保本仓往往是零息债加看涨，与领口的资金来源不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先画到期支付：每条腿的斜率 \\(\\pm1\\) 或 \\(0\\)，组合斜率是整数。再在同一曲面模型下对腿求和得到价值与希腊值；允许净 Delta 用期货对冲，使组合变成纯波动/偏斜仓。日历必须用同一标的、注意分红与提前行权（美式日历不是欧式日历）。报价：指数期权常用隐波点差；股票期权常用权利金。转换时不要把 Black 隐波差当成权利金差的线性。</p><p><span class="marginnote">牛市价差翻译成大白话：买一份便宜的看涨，同时卖一份更贵的看涨来「回血」权利金。代价是标的涨得再猛，收益到高执行价就封顶——你用放弃上侧的部分收益，换来了下跌时少亏一笔。</span></p><p><span class="marginnote">数字实例：标的现价 100 元，买执行价 100 的看涨付 3 元，卖执行价 105 的看涨收 1 元，净成本 2 元。到期若涨到 110，组合值 5 元，净赚 3 元；若跌到 95，两条腿都作废，最多亏这 2 元——收益和亏损都被封死了。</span></p><p>对冲频率按组合 Gamma 的寿命：蝶式 Gamma 集中在中间 \\(K\\) 附近且随到期收缩；日历在近月到期日有 pin 风险，见 <a href="/quant/pin-risk">Pin risk</a>。</p><p><span class="marginnote">常见误区：初学者以为蝶式中间那条腿风险大是因为「仓位大」，其实是到期前标的常停在中间执行价附近（pin），Gamma 全挤在那里，对冲最频繁、滑点吃掉的钱最多——风险来自对冲节奏，不是名义数量。</span></p>',15)),(n(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E4%B9%B0%E4%BD%8E%E6%89%A7%E8%A1%8C%E4%BB%B7%E7%9C%8B%E6%B6%A8%22%5D%20--%3E%20C%5B%22%E6%8B%BC%E6%88%90%E7%89%9B%E5%B8%82%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20B%5B%22%E5%8D%96%E9%AB%98%E6%89%A7%E8%A1%8C%E4%BB%B7%E7%9C%8B%E6%B6%A8%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20D%5B%22%E5%87%80%E6%9D%83%E5%88%A9%E9%87%91%EF%BC%9A%E5%80%9F%E6%96%B9%22%5D%0A%20%20C%20--%3E%20E%5B%22%E5%87%80Vega%E4%B8%8E%E5%87%80Gamma%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%87%80Delta%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20F%20--%3E%20G%5B%22%E7%94%A8%E6%9C%9F%E8%B4%A7%E5%AF%B9%E5%86%B2%E5%88%B0Delta%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%89%A9%E7%BA%AF%E6%B3%A2%E5%8A%A8%E4%B8%8E%E5%81%8F%E6%96%9C%E6%95%9E%E5%8F%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("线性组合不产生新的路径依赖：价值对路径的依赖仍只通过 \\(S_T\\)（欧式）或提前行权停时（美式）。它产生的是"),E("strong",null,"分段线性支付"),e("，从而把风险从「水平波动」拨到「斜率（偏斜）」或「凸性（密度）」。卖方簿若全是零售领口，聚合起来就是卖出上侧、买入下侧，偏斜会被供给推陡——这是结构供给，不是新的随机波动模型。")],-1)),(n(),o(s,null,{default:t(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Legs%5B%22%E9%A6%99%E8%8D%89%E8%85%BF%E7%BA%BF%E6%80%A7%E7%BB%84%E5%90%88%22%5D%20--%3E%20Vert%5B%22%E5%9E%82%E7%9B%B4%E4%BB%B7%E5%B7%AE%20%E9%80%BC%E8%BF%91%E6%95%B0%E5%AD%97%22%5D%0A%20%20Legs%20--%3E%20Fly%5B%22%E8%9D%B6%E5%BC%8F%20%E9%80%BC%E8%BF%91%E5%AF%86%E5%BA%A6%22%5D%0A%20%20Legs%20--%3E%20RR%5B%22%E9%A3%8E%E9%99%A9%E5%8F%8D%E8%BD%AC%20%E5%81%8F%E6%96%9C%22%5D%0A%20%20Legs%20--%3E%20Cal%5B%22%E6%97%A5%E5%8E%86%20%E8%BF%9C%E6%9C%9F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20Vert%20--%3E%20NoPath%5B%22%E4%BB%8D%E6%97%A0%E8%B7%AF%E5%BE%84%E7%BB%9F%E8%AE%A1%E9%87%8F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>美式、离散分红、涨跌停使支付图在到期前就可能被提前行权改写。多腿成交风险：一条腿成交、另一条没有，瞬时变成裸仓。保证金与组合保证金（SPAN 等）按情景，不按支付图的直觉名义。本课不写如何用组合规避持仓限额。</p><p>不要把「有界支付」当成有界风险：保证金、缺口、以及对冲滑点可以大于最大到期亏损。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>价差/跨式/蝶式/风险反转是香草线性组合，改支付斜率，不引入平均或极值。</li><li>垂直价差极限是数字，蝶式极限是密度；网格稀疏时残差仍在。</li><li>风险报告应按组合在曲面上取值，不要把腿的 Vega 当可加的独立预算。</li><li>出处：Natenberg, <em>Option Volatility and Pricing</em>；McMillan, <em>Options as a Strategic Investment</em>。</li></ul>',5))])}const _=B(d,[["render",m]]);export{C as __pageData,_ as default};
